    for r, c in sixes:
        out[r][c] = 0

    if not fours or not sixes:
        return out

    # A 6-object with its widest row at an end is a T: reflect the 4-object
    # sideways. A centered widest row indicates a vertical reflection.
    row_counts = {}
    for r, c in sixes:
        row_counts[r] = row_counts.get(r, 0) + 1
    widest = max(row_counts.values())
    wide_rows = [r for r, n in row_counts.items() if n == widest]
    top, bottom = min(row_counts), max(row_counts)
    sideways = any(r in (top, bottom) for r in wide_rows)

    if sideways:
        edge = max(c for r, c in fours)
        for r, c in fours:
            cc = 2 * edge + 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    else:
        edge = max(r for r, c in fours)
        for r, c in fours:
            rr = 2 * edge + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4

    return out
